/**
 * Extract worksheet title from range.
 *
 * Example: extractSheetTitle("testSheet!A1") ==> 'A1'
 * Example: extractSheetTitle("testSheet!A1:C3") ==> 'A1:C3'
 * Example: extractSheetTitle("'testSheet 1'!A1", true) ==> ['testSheet 1', 'A1'];
