    } elseif ($isSimpleCoordinate) {
        if ($collection->has($normalizedAddress)) {
            $resolvedCell = $collection->get($normalizedAddress);
            $xfIndex = $resolvedCell->getXfIndex();
        }
    } else {
        $useOriginalLookup = true;
    }

    if ($useOriginalLookup) {
        if ($activeSheet->cellExists($selectedCell)) {
            $xfIndex = $activeSheet->getCell($selectedCell)->getXfIndex();
        } else {
            $xfIndex = 0;
        }
    }

    return $activeSheet->getParentOrThrow()->getCellXfByIndex($xfIndex);
}

